use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::{AgentResponse, Intent, LlmError};

/// Bounded tool-orchestration loop: at most this many model rounds.
const MAX_ROUNDS: usize = 4;
/// Upper bound on the accumulated prompt, including tool results.
const MAX_PROMPT_BYTES: usize = 16 * 1024;
/// Upper bound on a single lookup query the model asks for.
const MAX_QUERY_BYTES: usize = 512;
/// The only tool this node is granted (its `LLMClient<[lookup]>` scope).
const TOOL_LOOKUP: &str = "lookup";

struct Node;

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        generate_response(ctx)
    }
}

export!(Node);

fn generate_response(ctx: ConversationContext) -> ResponseResult {
    let system = system_prompt(ctx.intent, &ctx.knowledge);
    let mut prompt = format!("Customer question: {}", ctx.question);

    for _ in 0..MAX_ROUNDS {
        match tool_llm::generate(&system, &prompt) {
            Reply::Text(text) => {
                return ResponseResult::Ok(AgentResponse { text });
            }
            Reply::Call(req) => {
                if req.tool != TOOL_LOOKUP {
                    return fail("model requested a tool outside this node's scope");
                }
                if req.query.len() > MAX_QUERY_BYTES {
                    return fail("lookup query exceeds size limit");
                }
                let hits = kb_read::lookup(&req.query);
                let block = format_hits(&req.query, &hits);
                if prompt.len() + block.len() > MAX_PROMPT_BYTES {
                    return fail("tool results exceed prompt budget");
                }
                prompt.push_str(&block);
            }
        }
    }

    fail("tool-call budget exhausted without an answer")
}

fn fail(message: &str) -> ResponseResult {
    ResponseResult::Error(LlmError {
        message: message.to_string(),
    })
}

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing question",
        Intent::TechnicalSupport => "technical support",
        Intent::AccountChange => "account change",
        Intent::GeneralInquiry => "general inquiry",
        Intent::Unknown => "unknown",
    }
}

fn system_prompt(intent: Intent, knowledge: &[String]) -> String {
    let mut s = format!(
        "You are a customer-support assistant. The customer's intent is: {}.\n",
        intent_label(intent)
    );
    s.push_str(
        "Answer the customer's question. If you need more information, call the \
         lookup tool with a search query. You may do so only a few times.\n",
    );
    if !knowledge.is_empty() {
        s.push_str("Context provided for this conversation:\n");
        for k in knowledge {
            s.push_str("- ");
            s.push_str(k);
            s.push('\n');
        }
    }
    s
}

fn format_hits(query: &str, hits: &[String]) -> String {
    let mut out = format!("\n\nKnowledge base results for \"{query}\":\n");
    if hits.is_empty() {
        out.push_str("(no matches)\n");
    }
    for h in hits {
        out.push_str("- ");
        out.push_str(h);
        out.push('\n');
    }
    out
}
